##REVC
print(f"\nREVC: ")

REVC_seq = ""

def reverse_complement(REVC_seq):
    complement = str.maketrans("ATCG", "TAGC")
    return REVC_seq.translate(complement)[::-1]

print(reverse_complement(REVC_seq))  